const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(
    new Cesium.OpenStreetMapImageryProvider({
      url: 'https://tile.openstreetmap.org/',
      maximumLevel: 18,
    })
  ),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;
viewer.clock.shouldAnimate = true;

// --- Crater position ---
const craterLng = -122.1944;
const craterLat = 46.1914;
const craterAlt = 2549;
const craterPosition = Cesium.Cartesian3.fromDegrees(craterLng, craterLat, craterAlt);

// --- Translucent grey radial-gradient canvas ---
function makeSmokeCanvas() {
  const size = 64;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  const cx = size / 2;
  const cy = size / 2;
  const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, cx);
  grad.addColorStop(0.0, 'rgba(180, 170, 165, 0.90)');
  grad.addColorStop(0.4, 'rgba(160, 150, 145, 0.55)');
  grad.addColorStop(0.75, 'rgba(140, 130, 125, 0.20)');
  grad.addColorStop(1.0, 'rgba(120, 110, 105, 0.00)');
  ctx.clearRect(0, 0, size, size);
  ctx.beginPath();
  ctx.arc(cx, cy, cx, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();
  return canvas;
}

// --- Particle system ---
const smokeSystem = new Cesium.ParticleSystem({
  image: makeSmokeCanvas(),
  startColor: new Cesium.Color(0.72, 0.68, 0.65, 0.80),
  endColor:   new Cesium.Color(0.88, 0.85, 0.82, 0.00),
  startScale: 1.4,
  endScale:   8.0,
  emissionRate: 60,
  minimumParticleLife: 4,
  maximumParticleLife: 8,
  minimumSpeed: 8,
  maximumSpeed: 16,
  imageSize: new Cesium.Cartesian2(30, 30),
  emitter: new Cesium.CircleEmitter(4.0),
  modelMatrix: Cesium.Transforms.eastNorthUpToFixedFrame(craterPosition),
  lifetime: Number.MAX_VALUE,
  loop: true,
  sizeInMeters: false,
});
viewer.scene.primitives.add(smokeSystem);

// --- Dark crater marker ellipse ---
viewer.entities.add({
  name: 'Mount St. Helens Crater',
  position: craterPosition,
  ellipse: {
    semiMajorAxis: 120,
    semiMinorAxis: 90,
    rotation: Cesium.Math.toRadians(15),
    height: craterAlt,
    material: new Cesium.ColorMaterialProperty(new Cesium.Color(0.12, 0.08, 0.06, 0.85)),
    outline: true,
    outlineColor: new Cesium.Color(0.55, 0.40, 0.25, 1.0),
    outlineWidth: 2,
  },
});

// --- Oblique camera view looking up at the plume ---
// Place camera ~2800 m southwest of crater, elevated ~600 m above crater
viewer.camera.lookAt(
  craterPosition,
  new Cesium.HeadingPitchRange(
    Cesium.Math.toRadians(225),   // heading: look from SW toward NE
    Cesium.Math.toRadians(-22),   // pitch: ~22° below horizontal, sees plume rising
    3200                          // range: 3.2 km — plume visible, not blobbified
  )
);
